(()=>{"use strict";if(!navigator.cookieEnabled)return;const e=(new Date).getTimezoneOffset(),t=Intl.DateTimeFormat().resolvedOptions().timeZone;fetch(window.tz_set_endpoint,{method:"POST",headers:{[window.csrf_header_name]:window.csrf_token,"X-Requested-With":"XMLHttpRequest"},body:new URLSearchParams({offset:e,timezone:t})}).then(n=>{n.ok&&document.dispatchEvent(new CustomEvent("tzdetect:set",{detail:{timezone:t,offset:e}}))})})();
